DO $$ DECLARE name text; definition text; BEGIN FOREACH name IN ARRAY ARRAY['record_question','vote_group','divide_session','apply_grouping','publish_group','register_participant','create_quick_check'] LOOP SELECT pg_get_functiondef(p.oid) INTO definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=name; IF name='record_question' THEN definition:=replace(definition,'WHERE id = _session_id FOR UPDATE','WHERE id = _session_id AND created_at>now()-interval ''6 hours'' FOR UPDATE'); ELSE definition:=replace(definition,'status=''LIVE'' FOR UPDATE','status=''LIVE'' AND created_at>now()-interval ''6 hours'' FOR UPDATE'); END IF; EXECUTE definition; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.expire_session(_code text) RETURNS SETOF public.sessions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sess public.sessions; BEGIN SELECT * INTO sess FROM public.sessions WHERE code=_code FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; IF sess.status='LIVE' AND sess.created_at<=now()-interval '6 hours' THEN UPDATE public.sessions SET status='ENDED',ended_at=now(),public_version=public_version+1,activity_version=activity_version+1 WHERE id=sess.id RETURNING * INTO sess; END IF; IF sess.status='ENDED' AND sess.ended_at<=now()-interval '24 hours' THEN DELETE FROM public.sessions WHERE id=sess.id; RETURN; END IF; RETURN NEXT sess; END $$;
REVOKE EXECUTE ON FUNCTION public.expire_session(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.expire_session(text) TO service_role;
COMMENT ON COLUMN public.sessions.lecture_context IS 'DEPRECATED: private lecture_context table replaces this column; must remain NULL';
ALTER TABLE public.sessions ADD CONSTRAINT sessions_no_legacy_context CHECK (lecture_context IS NULL) NOT VALID;
ALTER TABLE public.sessions VALIDATE CONSTRAINT sessions_no_legacy_context;
REVOKE ALL ON public.activities,public.activity_responses,public.explain_submissions,public.group_votes,public.lecture_context,public.question_groups,public.questions,public.session_divisions,public.session_participants,public.session_secrets,public.takeaway_drafts,public.takeaways FROM anon,authenticated;
REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON public.sessions FROM anon,authenticated;
GRANT SELECT ON public.sessions TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sweep_sessions() TO service_role;